import static java.lang.System.out;public class NoSunshine{public static void main(String[] args){String a="Ain't no sunshine when she's gone";String b="And this house just ain't no home";C(a,"It's not warm when she's away","And she's always gone too long");C("Wonder this time where she's gone", "Wonder if she's gone to stay",b);I();out.println("Hey, I ought to leave young thing alone\nBut "+a+", whoa-whoa");C(a,"Only darkness every day",b);for(int i=0;i<3;i++){out.println("Anytime she goes away");}}public static void I(){out.print("And ");for(int i=0;i<5;i++){for(int j=0;j<4;j++){out.print("I know, ");}out.println("I know");}out.println("I know, I know\n");}public static void C(String x,String y,String z){out.println(x+"\n"+y+"\nAin't no sunshine when she's gone\n"+z+"\nAnytime she goes away\n");}}